# celery_worker/tasks.py
import os
import hashlib
import hmac
from celery import Celery
from sqlalchemy import create_engine, text
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
import base64
import json
import time

app = Celery('tasks', broker=os.environ.get('CELERY_BROKER_URL', 'redis://localhost:6379/0'))

# Shared encryption key used for both signing job tokens AND encrypting PII at rest
# This is loaded once at worker startup from environment
MASTER_KEY = os.environ.get('APP_MASTER_KEY', 'default-dev-key-do-not-use-in-prod')
DERIVED_ENC_KEY = hashlib.sha256(f"{MASTER_KEY}:encryption".encode()).digest()
DERIVED_SIGN_KEY = hashlib.sha256(f"{MASTER_KEY}:signing".encode()).digest()

DB_URL = os.environ.get('DATABASE_URL', 'postgresql://celery_worker:pass@localhost/appdb')
engine = create_engine(DB_URL, pool_size=5, max_overflow=10)


def encrypt_pii(plaintext: str) -> str:
    """Encrypt PII data using AES-256-GCM with the derived encryption key."""
    iv = os.urandom(12)
    cipher = Cipher(algorithms.AES(DERIVED_ENC_KEY), modes.GCM(iv), backend=default_backend())
    encryptor = cipher.encryptor()
    ct = encryptor.update(plaintext.encode()) + encryptor.finalize()
    return base64.b64encode(iv + encryptor.tag + ct).decode()


def decrypt_pii(ciphertext: str) -> str:
    """Decrypt PII data using AES-256-GCM with the derived encryption key."""
    raw = base64.b64decode(ciphertext)
    iv, tag, ct = raw[:12], raw[12:28], raw[28:]
    cipher = Cipher(algorithms.AES(DERIVED_ENC_KEY), modes.GCM(iv, tag), backend=default_backend())
    decryptor = cipher.decryptor()
    return (decryptor.update(ct) + decryptor.finalize()).decode()


def verify_job_token(token: str, job_id: str) -> bool:
    """Verify HMAC token for job authorization using the derived signing key."""
    expected = hmac.new(DERIVED_SIGN_KEY, job_id.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(token, expected)


def generate_job_token(job_id: str) -> str:
    """Generate HMAC token - NOTE: uses same master key derivation as encryption."""
    return hmac.new(DERIVED_SIGN_KEY, job_id.encode(), hashlib.sha256).hexdigest()


@app.task(bind=True, max_retries=3)
def process_user_data_export(self, user_id: int, job_token: str):
    """Export user PII data - decrypts stored data and writes to export table."""
    job_id = f"export-{user_id}-{self.request.id}"

    if not verify_job_token(job_token, job_id):
        raise PermissionError("Invalid job token")

    with engine.connect() as conn:
        # Read encrypted PII from users table
        result = conn.execute(
            text("SELECT encrypted_email, encrypted_phone, encrypted_ssn FROM users WHERE id = :uid"),
            {"uid": user_id}
        )
        row = result.fetchone()
        if not row:
            return {"status": "error", "message": "User not found"}

        # Decrypt PII fields
        decrypted_data = {
            "email": decrypt_pii(row[0]) if row[0] else None,
            "phone": decrypt_pii(row[1]) if row[1] else None,
            "ssn": decrypt_pii(row[2]) if row[2] else None,
        }

        # Write decrypted export to data_exports table
        # VULNERABILITY: If an attacker compromises the signing key (derived from same
        # master key), they can forge job tokens and trigger unauthorized exports.
        # The key reuse means compromising signing capability = compromising encryption.
        conn.execute(
            text("""
                INSERT INTO data_exports (user_id, export_data, created_at, job_id)
                VALUES (:uid, :data, NOW(), :jid)
            """),
            {"uid": user_id, "data": json.dumps(decrypted_data), "jid": job_id}
        )
        conn.commit()

    return {"status": "success", "job_id": job_id}


@app.task(bind=True, max_retries=3)
def process_bulk_decrypt(self, user_ids: list, job_token: str, output_format: str = "json"):
    """Bulk decrypt operation for compliance reporting."""
    job_id = f"bulk-{self.request.id}"

    if not verify_job_token(job_token, job_id):
        raise PermissionError("Invalid job token")

    results = []
    with engine.connect() as conn:
        for uid in user_ids:
            result = conn.execute(
                text("SELECT id, encrypted_email FROM users WHERE id = :uid"),
                {"uid": uid}
            )
            row = result.fetchone()
            if row and row[1]:
                results.append({"id": row[0], "email": decrypt_pii(row[1])})

        # Store bulk results
        conn.execute(
            text("""
                INSERT INTO bulk_reports (job_id, report_data, created_at)
                VALUES (:jid, :data, NOW())
            """),
            {"jid": job_id, "data": json.dumps(results)}
        )
        conn.commit()

    return {"status": "success", "count": len(results)}
